import * as THREE from'three';import{mergeGeometries}from'./vendor/BufferGeometryUtils.js';
import{GLTFLoader}from'./vendor/GLTFLoader.js';
// Each interactive GLB node retains its identity through the Blender export.
const bytes104=new Map();
export async function loadBench103(id){if(!bytes104.has(id))bytes104.set(id,(async()=>{const r=await fetch(`./models/mantenimiento103/${id}.glb.gz?v=148`);if(!r.ok)throw Error('GLB '+r.status);return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();})().catch(e=>{bytes104.delete(id);throw e;}));const gltf=await new GLTFLoader().parseAsync((await bytes104.get(id)).slice(0),''),group=gltf.scene,parts={},pickRoots=[],homes=new Map();group.traverse(o=>{if(o.name.startsWith('m103_'))parts[o.name.slice(5)]=o;});for(const p of Object.values(parts)){homes.set(p,p.position.clone());if(p.userData.handTarget){pickRoots.push(p);const own=new Map();p.traverse(o=>{if(o.material){if(!own.has(o.material))own.set(o.material,o.material.clone());o.material=own.get(o.material);}});}}batchBench104(group,parts);const bulb=group.getObjectByName('m103_lamp');bulb?.traverse(o=>{if(o.material?.name.startsWith('m103_bulb'))parts.bulbMaterial=o.material;});for(const key of ['power','tray','switchLever','meter'])if(!parts[key])throw Error('GLB sin '+key);return upgradeTrain142(await houseTrain138(detailBench125(finishBench122(detailBench118({group,parts,pickRoots,homes,id,materials:{}})))));}

export function batchBench104(group,parts){group.updateMatrixWorld(true);const named=new Set(Object.values(parts)),anchors=[group,...named].filter(o=>o?.isObject3D&&!o.isMesh);for(const anchor of anchors){const batches=new Map(),inverse=anchor.matrixWorld.clone().invert();anchor.traverse(o=>{if(!o.isMesh||named.has(o)||Array.isArray(o.material))return;let parent=o.parent;while(parent&&parent!==anchor&&!named.has(parent))parent=parent.parent;if(parent!==anchor)return;const key=o.material.uuid+':'+Object.keys(o.geometry.attributes).sort().join(',');if(!batches.has(key))batches.set(key,[]);batches.get(key).push(o);});for(const meshes of batches.values()){if(meshes.length<2)continue;const gs=meshes.map(o=>o.geometry.clone().applyMatrix4(new THREE.Matrix4().multiplyMatrices(inverse,o.matrixWorld))),geometry=mergeGeometries(gs,false);gs.forEach(g=>g.dispose());if(!geometry)continue;const mesh=new THREE.Mesh(geometry,meshes[0].material);mesh.name='Superficies agrupadas104';for(const o of meshes){o.removeFromParent();o.geometry.dispose();}anchor.add(mesh);}}}
